def parse_config_value(value: str, target_type: str):
    if target_type == 'int':
        return int(value)
    elif target_type == 'float':
        return float(value)
    elif target_type == 'bool':
        low = value.strip().lower()
        if low in ('true', 'yes', '1'):
            return True
        elif low in ('false', 'no', '0'):
            return False
        else:
            raise ValueError(f"cannot parse '{value}' as bool")
    elif target_type == 'str':
        return value
    elif target_type == 'list[int]':
        parts = [p.strip() for p in value.split(',') if p.strip()]
        if not parts:
            raise ValueError('empty list')
        result = []
        for p in parts:
            result.append(int(p))
        return result
    else:
        raise ValueError(f"unsupported type: {target_type}")

def filter_logs(logs: list[dict], min_level: str) -> list[dict]:
    levels = {'DEBUG': 0, 'INFO': 1, 'WARN': 2, 'ERROR': 3, 'FATAL': 4}
    if min_level not in levels:
        raise ValueError(f"unknown level: {min_level}")
    min_val = levels[min_level]
    result = []
    for log in logs:
        level = log.get('level', '').upper()
        if level in levels and levels[level] >= min_val:
            result.append(log)
    result.sort(key=lambda x: x.get('timestamp', ''))
    return result

