def deep_merge(base: dict, override: dict, conflict: str = 'overwrite') -> dict:
    if conflict not in ('overwrite', 'ignore', 'merge'):
        raise ValueError(f"unknown conflict strategy: {conflict}")
    result = base.copy()
    for key, val in override.items():
        if key not in result:
            result[key] = val
        elif isinstance(result[key], dict) and isinstance(val, dict):
            result[key] = deep_merge(result[key], val, conflict)
        elif conflict == 'overwrite':
            result[key] = val
        elif conflict == 'ignore':
            pass
        elif conflict == 'merge':
            result[key] = val
    return result

