def group_aggregate(data: list[dict], group_by: str, agg_field: str, agg_func: str) -> list[dict]:
    if agg_func not in ('sum', 'avg', 'count', 'max', 'min'):
        raise ValueError(f"unsupported agg_func: {agg_func}")
    groups = {}
    for row in data:
        key = row.get(group_by)
        val = row.get(agg_field, 0)
        if key not in groups:
            groups[key] = {'vals': [], 'count': 0}
        groups[key]['vals'].append(val if val is not None else 0)
        groups[key]['count'] += 1
    result = []
    for key, info in groups.items():
        vals = info['vals']
        if agg_func == 'sum':
            agg_val = sum(vals)
        elif agg_func == 'avg':
            agg_val = round(sum(vals) / len(vals), 2) if vals else 0
        elif agg_func == 'count':
            agg_val = info['count']
        elif agg_func == 'max':
            agg_val = max(vals)
        elif agg_func == 'min':
            agg_val = min(vals)
        result.append({group_by: key, agg_field: agg_val, 'count': info['count']})
    result.sort(key=lambda x: x[agg_field], reverse=True)
    return result

