class PaginatedIterator:
    def __init__(self, all_data: list, page_size: int):
        self._all_data = all_data
        self._page_size = page_size
        self._index = 0

    def __iter__(self):
        return self

    def __next__(self) -> list:
        if self._index >= len(self._all_data):
            raise StopIteration
        start = self._index
        end = min(start + self._page_size, len(self._all_data))
        page = self._all_data[start:end]
        self._index = end
        return page

def parse_log_lines(log_lines: list[str]) -> list[dict]:
    def _generator():
        for line in log_lines:
            stripped = line.strip()
            if not stripped or stripped.startswith('#'):
                continue
            parts = [p.strip() for p in stripped.split('|')]
            if len(parts) != 4:
                continue
            yield {
                'level': parts[0],
                'timestamp': parts[1],
                'module': parts[2],
                'message': parts[3],
            }
    return list(_generator())

