def flatten_json(obj, parent_key=""):
    result = {}
    for k, v in obj.items():
        nk = f"{parent_key}.{k}" if parent_key else k
        if isinstance(v, dict):
            result.update(flatten_json(v, nk))
        elif isinstance(v, list):
            for i, item in enumerate(v):
                result[f"{nk}.{i}"] = item
        else:
            result[nk] = v
    return result

